// ======= SET THIS TO true WHILE TESTING, false FOR REAL USE =======
const TESTING = true;

// Set to false only to test calls outside business hours. Leave true in production.
const ENFORCE_CALL_WINDOW = false;

// Every timestamp in the sheet is written in TZ so they stay comparable to each other.
// CALLING HOURS, though, are always judged in the client's own zone.
const TZ = 'Asia/Kolkata';
const DEFAULT_TZ = 'Asia/Kolkata'; // used when a row has no usable time zone

const SEC_BEFORE_FOLLOWUP_1 = TESTING ? 10 : 2 * 24 * 60 * 60;   // 2 days in prod
const SEC_BEFORE_FOLLOWUP_2 = TESTING ? 20 : 4 * 24 * 60 * 60;   // 4 days in prod
const SEC_BEFORE_FOLLOWUP_3 = TESTING ? 30 : 6 * 24 * 60 * 60;   // 6 days in prod
const SEC_BEFORE_CALL       = TESTING ? 40 : 2 * 24 * 60 * 60;   // call 2 days after Follow up 2
const SEC_CALL_LOCK         = TESTING ? 180 : 15 * 60;           // 'Calling' older than this is stale

const MAX_CALL_ATTEMPTS    = 3; // first call + two retries
const MAX_CONCURRENT_CALLS = 6; // the plan allows six live calls at once

const fmt = 'dd MMM yyyy HH:mm:ss';
const parse = (str) => (str ? DateTime.fromFormat(String(str), fmt, { zone: TZ }) : null);
const now = DateTime.now().setZone(TZ);

// ---------------------------------------------------------------- client time zone
// The sheet stores it as 'Europe/Rome (UTC+02:00)', so the IANA name is everything before
// the bracket. If Luxon does not recognise that name, fall back to the raw UTC offset, then
// to DEFAULT_TZ, so one messy cell can never stop a lead being worked.
const resolveZone = (raw) => {
  const text = (raw || '').toString().trim();
  if (!text) return DEFAULT_TZ;

  const iana = text.split('(')[0].trim().replace(/\s+/g, '_');
  if (iana && DateTime.now().setZone(iana).isValid) return iana;

  const m = text.match(/UTC\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?/i);
  if (m) {
    const offset = 'UTC' + m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00');
    if (DateTime.now().setZone(offset).isValid) return offset;
  }
  return DEFAULT_TZ;
};

// ---------------------------------------------------------------- calling hours
//   Tue / Wed / Thu   13:00 - 16:00
//   Fri               12:00 - 16:00
//   Mon / Sat / Sun   no calls at all
// Luxon weekday: 1 = Monday ... 7 = Sunday.
const WINDOWS = { 2: [13, 16], 3: [13, 16], 4: [13, 16], 5: [12, 16] };
const TAIL_BUFFER_MIN = 10; // never start a call that would still be running at closing

const windowEdges = (dt) => {
  const w = WINDOWS[dt.weekday];
  if (!w) return null;
  return {
    open: dt.set({ hour: w[0], minute: 0, second: 0, millisecond: 0 }),
    lastStart: dt.set({ hour: w[1], minute: 0, second: 0, millisecond: 0 })
      .minus({ minutes: TAIL_BUFFER_MIN })
  };
};

const canCallNow = (dt) => {
  const e = windowEdges(dt);
  return !!e && dt.toMillis() >= e.open.toMillis() && dt.toMillis() < e.lastStart.toMillis();
};

const rows = $input.all().map((item, index) => ({ d: item.json, index }));

// ---------------------------------------------------------------- concurrency
// Six calls may be live at once. Anything left 'Calling' for longer than the lock window is
// treated as stale, so a lost webhook can never eat a slot forever.
let liveCalls = 0;
for (const { d } of rows) {
  if ((d['Call Status'] || '').toString().trim().toLowerCase() !== 'calling') continue;
  const startedAt = parse(d['call_started_at']);
  const ageSec = startedAt && startedAt.isValid
    ? now.diff(startedAt, 'seconds').seconds
    : Number.MAX_SAFE_INTEGER;
  if (ageSec < SEC_CALL_LOCK) liveCalls++;
}
const freeSlots = Math.max(0, MAX_CONCURRENT_CALLS - liveCalls);

const callActions = [];
const emailActions = [];

for (const { d, index } of rows) {
  const status = parse(d['Status']);
  const f1 = parse(d['Follow up 1']);
  const f2 = parse(d['Follow up 2']);
  const retryAt = parse(d['call_retry_at']);
  const startedAt = parse(d['call_started_at']);

  const callStatus = (d['Call Status'] || '').toString().trim();
  const callStatusLower = callStatus.toLowerCase();
  const hasEmail = (d['Email'] || '').toString().trim().length > 0;
  const hasPhone = (d['phone_number'] || '').toString().trim().length > 0;
  const attempts = Number(d['call_attempt_count'] || 0);
  const callingAgeSec = startedAt && startedAt.isValid
    ? now.diff(startedAt, 'seconds').seconds
    : Number.MAX_SAFE_INTEGER;

  const zone = resolveZone(d['time zone']);
  const localNow = now.setZone(zone);
  // Explicit "call me later" requests honour the client's exact time, including Mon/Sat/Sun
  // and hours outside the window. First calls and failed-call retries still need the window.
  const isExplicitCallback = callStatusLower === 'callback scheduled';
  const windowOpen = !ENFORCE_CALL_WINDOW || isExplicitCallback || canCallNow(localNow);

  // Dead ends for the agent: bad number, every attempt used, or a real person has taken
  // over because a meeting / assessment was booked.
  const handedToHuman = callStatusLower.includes('human follow-up')
    || callStatusLower.includes('needs review');
  const noRetryEver = callStatusLower.includes('no retry')
    || callStatusLower.includes('exhausted')
    || handedToHuman;

  // ---------- calls ----------
  // A lead that is due but outside its own business hours is simply not queued this run
  // (except explicit callbacks — those dial whenever the client asked).
  // The scheduler ticks every few minutes, so windowed calls get picked up when it opens.
  if (hasPhone && !noRetryEver && attempts < MAX_CALL_ATTEMPTS && windowOpen) {
    let queued = null;

    if (callStatusLower === 'pending call') {
      // Email leads wait until two days after Follow up 2. No-email leads go straight in.
      const waitsForFollowUps = hasEmail && f2 && f2.isValid;
      if (!waitsForFollowUps) {
        queued = [6, 'first call (no email lead)'];
      } else if (now.diff(f2, 'seconds').seconds >= SEC_BEFORE_CALL) {
        queued = [4, 'first call after follow-up 2'];
      }
    } else if (callStatusLower === 'callback scheduled'
      && retryAt && retryAt.isValid && now.toMillis() >= retryAt.toMillis()) {
      queued = [7, 'callback requested by client'];
    } else if (callStatusLower.includes('retry scheduled')
      && retryAt && retryAt.isValid && now.toMillis() >= retryAt.toMillis()) {
      queued = [5, 'retry after no answer / declined / unreachable'];
    } else if (callStatusLower === 'calling' && callingAgeSec >= SEC_CALL_LOCK) {
      queued = [5, 'recover stale call'];
    } else if (!callStatus && hasEmail && f2 && f2.isValid
      && now.diff(f2, 'seconds').seconds >= SEC_BEFORE_CALL) {
      // Rows that finished the email sequence before 'Pending Call' existed.
      queued = [4, 'first call after follow-up 2 (legacy row)'];
    }

    if (queued) {
      callActions.push({
        json: {
          ...d,
          nextFollowUp: queued[0],
          callReason: queued[1],
          client_timezone: zone,
          client_local_time: localNow.toFormat('cccc, dd MMM yyyy HH:mm')
        },
        pairedItem: index
      });
      // Never email someone in the same run we are dialling them.
      continue;
    }
  }

  // ---------- follow-up emails ----------
  // Emails ignore calling hours. Follow up 3 still goes out on its own schedule even though
  // the call is now triggered from Follow up 2, so the two run side by side.
  if (!hasEmail) continue;
  // Do not email while the agent is actually on the phone with them.
  if (callStatusLower === 'calling' && callingAgeSec < SEC_CALL_LOCK) continue;

  if (status && status.isValid && !d['Follow up 1']
    && now.diff(status, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_1) {
    emailActions.push({ json: { ...d, nextFollowUp: 1 }, pairedItem: index });
  } else if (f1 && f1.isValid && !d['Follow up 2']
    && now.diff(f1, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_2) {
    emailActions.push({ json: { ...d, nextFollowUp: 2 }, pairedItem: index });
  } else if (f2 && f2.isValid && !d['Follow up 3']
    && now.diff(f2, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_3) {
    emailActions.push({ json: { ...d, nextFollowUp: 3 }, pairedItem: index });
  }
}

const releasedCalls = callActions.slice(0, freeSlots);

return [...releasedCalls, ...emailActions];

