// conversation we need to inspect, the counters we have to carry forward, and the client's
// time zone, which decides when any callback may actually be dialled.
const hook = $('Webhook').first().json;
const body = hook.body || hook;

const leadId = (body.lead_id || body.leadId || '').toString().trim();
if (!leadId) {
  return [];
}

const row = $input
  .all()
  .map((item) => item.json)
  .find((r) => (r['Serial No'] || '').toString().trim() === leadId);

return [{
  json: {
    lead_id: leadId,
    body,
    conversation_id: row ? (row.conversation_id || '').toString().trim() : '',
    call_attempt_count: row ? Number(row.call_attempt_count || 1) : 1,
    callback_count: row ? Number(row.callback_count || 0) : 0,
    previous_call_status: row ? (row['Call Status'] || '').toString() : '',
    time_zone: row ? (row['time zone'] || '').toString() : ''
  }
