    open: dt.set({ hour: w[0], minute: 0, second: 0, millisecond: 0 }),
    lastStart: dt.set({ hour: w[1], minute: 0, second: 0, millisecond: 0 })
      .minus({ minutes: TAIL_BUFFER_MIN })
  };
};

const nextCallableMoment = (dt) => {
  let cursor = dt;
  for (let i = 0; i < 15; i++) {
    const e = windowEdges(cursor);
    if (e) {
      if (cursor.toMillis() < e.open.toMillis()) return e.open;
      if (cursor.toMillis() < e.lastStart.toMillis()) return cursor;
    }
    cursor = cursor.plus({ days: 1 }).startOf('day');
  }
  return dt;
};

// What a human reads in the sheet: the client's own wall clock, with the zone spelled out
// so nobody has to guess whose 2pm it is.
const localLabel = (dt) => dt.setZone(zone).toFormat('dd MMM yyyy HH:mm') + ' ' + zone;

// ---------------------------------------------------------------- agent's answers
// Field names differ depending on how the data collection is set up in ElevenLabs,
// so accept the usual spellings rather than one hardcoded key.
const pick = (...keys) => {
  for (const src of [body, body.data || {}]) {
    for (const key of keys) {
      let value = src[key];
      if (value && typeof value === 'object' && 'value' in value) value = value.value;
      if (value !== undefined && value !== null && value.toString().trim() !== '') {
        return value.toString().trim();
      }
    }
  }
  return '';
};

let rawMeeting = pick(
  'meeting_datetime', 'meeting_schedule_time', 'meeting_time', 'meeting_scheduled_at',
  'assessment_datetime', 'assessment_schedule_time', 'assessment_time',
  'appointment_datetime', 'appointment_time', 'demo_datetime'
);
let rawCallback = pick('callback_datetime', 'callback_time', 'call_back_datetime', 'callback_at');

const outcomeText = `${body.lead_outcome || ''} ${body.next_action || ''} ${pick('meeting_type') || ''}`.toLowerCase();
const bookingWords = ['meeting', 'assessment', 'appointment', 'demo', 'consultation', 'audit', 'booked'];
const saysBooked = bookingWords.some((word) => outcomeText.includes(word));

// Safety net for agents that only have the callback field wired up: if the outcome says a
// booking was made, treat that timestamp as the meeting, never as a robot callback.
if (!rawMeeting && rawCallback && saysBooked) {
  rawMeeting = rawCallback;
  rawCallback = '';
}

let meetingType = pick('meeting_type', 'appointment_type');
if (!meetingType && rawMeeting) {
  if (outcomeText.includes('assessment') || outcomeText.includes('audit')) meetingType = 'Assessment';
  else if (outcomeText.includes('demo')) meetingType = 'Demo';
  else meetingType = 'Meeting';
}

// The agent answers in whatever shape the conversation took, and it is prompted to name the
// prospect's own zone, e.g. '21 Aug 2026 2:00 PM America/New_York'. A named zone or an
// explicit UTC offset is trusted, because both identify one exact instant. A bare
// abbreviation like EST is not: it means different things in different countries, so it is
// dropped and the time is read on the lead's own clock instead. We never fall back to OUR
// zone, or a New York 2pm silently becomes 2pm IST. If nothing parses we refuse to guess a
// dial time and hand the row to a human.
const TZ_WORDS = /\b(?:UTC|GMT|IST|EST|EDT|CST|CDT|MST|MDT|PST|PDT|BST|CET|CEST|EET|EEST|JST|KST|AEST|AEDT|AWST|SGT|HKT|NZST|NZDT|MSK|WAT|SAST|BRT)\b/gi;
const DATE_FORMATS = [
  'dd MMM yyyy HH:mm:ss', 'd MMM yyyy H:mm:ss',
  'dd MMM yyyy HH:mm', 'd MMM yyyy H:mm', 'd MMM yyyy h:mm a',
  'd MMMM yyyy H:mm', 'd MMMM yyyy h:mm a',
  'MMM d yyyy H:mm', 'MMM d yyyy h:mm a',
  'MMMM d yyyy H:mm', 'MMMM d yyyy h:mm a',
  'yyyy-M-d H:mm', 'yyyy-M-d h:mm a',
  'd/M/yyyy H:mm', 'd/M/yyyy h:mm a',
  'd-M-yyyy H:mm', 'd-M-yyyy h:mm a',
  'ccc d MMM yyyy H:mm', 'ccc d MMM yyyy h:mm a',
  'cccc d MMM yyyy H:mm', 'cccc d MMM yyyy h:mm a',
  'ccc d MMMM yyyy h:mm a', 'cccc d MMMM yyyy h:mm a',
  // Day with no time: nextCallableMoment turns that midnight into the window opening.
  'd MMM yyyy', 'd MMMM yyyy', 'yyyy-M-d', 'd/M/yyyy', 'd-M-yyyy'
];

const toDateTime = (raw) => {
  if (!raw) return null;
  let text = raw.toString().trim();
  let useZone = zone;

  const named = text.match(/([A-Za-z]{3,}\/[A-Za-z_]+(?:\/[A-Za-z_]+)?)/);
  if (named && DateTime.now().setZone(named[1]).isValid) {
    useZone = named[1];
    text = text.replace(named[1], ' ');
  } else {
    const off = text.match(/\b(?:UTC|GMT)\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?/i);
    if (off) {
      const candidate = 'UTC' + off[1] + off[2].padStart(2, '0') + ':' + (off[3] || '00');
      if (DateTime.now().setZone(candidate).isValid) useZone = candidate;
    }
  }

  text = text.replace(/\b(?:UTC|GMT)\s*[+-]\s*\d{1,2}(?::?\d{2})?/gi, ' ').replace(TZ_WORDS, ' ');
  // '2 p.m.' and '2pm' both become '2:00 PM', so one set of tokens covers every spelling.
  text = text.replace(/\b(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s?m\.?(?![a-z])/gi,
    (whole, h, mi, ap) => h + ':' + (mi || '00') + ' ' + ap.toUpperCase() + 'M');
  text = text.replace(/\bat\b/gi, ' ').replace(/,/g, ' ');
  text = text.replace(/\s+/g, ' ').replace(/[.\s]+$/, '').trim();
  if (!text) return null;

  const attemptsList = [
    () => DateTime.fromISO(text, { zone: useZone }),
    () => DateTime.fromSQL(text, { zone: useZone }),
    () => DateTime.fromRFC2822(text, { zone: useZone })
  ].concat(DATE_FORMATS.map((f) => () => DateTime.fromFormat(text, f, { zone: useZone })));

  for (const attempt of attemptsList) {
    try {
      const parsed = attempt();
      if (parsed && parsed.isValid) return parsed;
    } catch (err) {
      // try the next format
    }
  }
  return null;
};

// ---------------------------------------------------------------- was it a recording?
const announcementHints = [
  'does not exist',
  "doesn't exist",
  'not in service',
  'no longer in service',
  'out of service',
  'has been disconnected',
  'been disconnected',
  'unallocated',
  'not allocated',
  'unassigned',
  'not a valid number',
  'not a working number',
  'invalid number',
  'wrong number',
  'number you have dialed',
  'number you have dialled',
  'number you are trying to reach',
  'number you have called',
  'cannot be completed as dialed',
  'cannot be completed as dialled',
  'check the number',
  'number does not belong'
];

const transcript = Array.isArray(convo.transcript) ? convo.transcript : [];
// Whatever answered the call is transcribed as the 'user' side, so a recorded
// announcement shows up here just like a human would.
const otherSideText = transcript
  .filter((turn) => (turn && turn.role ? turn.role : '').toString().toLowerCase() !== 'agent')
  .map((turn) => (turn.message || turn.text || '').toString())
  .join(' ')
  .toLowerCase();

const heardAnnouncement = otherSideText.length > 0
  && announcementHints.some((hint) => otherSideText.includes(hint));

const meta = convo.metadata || {};
const durationSec = Number(meta.call_duration_secs || meta.callDurationSecs || 0);
const convoStatus = (convo.status || '').toString().toLowerCase();
// 'in-progress' means we fetched too early, so its transcript proves nothing.
const convoFinished = convoStatus !== '' && convoStatus !== 'in-progress' && convoStatus !== 'initiated';
const nobodySpoke = transcript.length > 0 && otherSideText.trim().length === 0;

// ---------------------------------------------------------------- verdict
let callStatus = 'Completed';
let leadOutcome = (body.lead_outcome || '').toString();
let lastOutcome = leadOutcome || 'answered';
let retryAt = '';
let attemptCount = attempts;
let newCallbackCount = callbackCount;
let meetingStamp = '';
let callbackStamp = '';
let meetingTypeOut = '';

if (heardAnnouncement) {
  // Not a real person. Never spend another attempt on it.
  leadOutcome = 'invalid_number';
  lastOutcome = 'Invalid Number';
  callStatus = 'Invalid Number - No Retry';
  attemptCount = MAX_CALL_ATTEMPTS;
} else if (nobodySpoke && convoFinished && durationSec > 0 && durationSec <= SHORT_CALL_SEC) {
  // Answered, but nothing came back: voicemail, dead air or a beep. Worth another try.
  leadOutcome = leadOutcome || 'no_response';
  lastOutcome = 'No Response';
  if (attempts < MAX_CALL_ATTEMPTS) {
    callStatus = 'No Response - Retry Scheduled';
    const target = now.setZone(zone).plus({ seconds: SEC_BEFORE_RETRY });
    const dialAt = ENFORCE_CALL_WINDOW ? nextCallableMoment(target) : target;
    retryAt = dialAt.setZone(TZ).toFormat(fmt);
  } else {
    callStatus = 'No Response - Retry Exhausted';
  }
} else if (rawMeeting) {
  // Interested and booked. A real person runs this one, so no dial time is ever set and the
  // time is never pushed into our calling hours: the client picked it, a human keeps it.
  const when = toDateTime(rawMeeting);
  meetingTypeOut = meetingType;
  meetingStamp = when ? localLabel(when) : rawMeeting; // keep the raw text if unparseable
  leadOutcome = leadOutcome || `${meetingType.toLowerCase()}_booked`;
  lastOutcome = `${meetingType} Booked`;
  callStatus = when
    ? `${meetingType} Scheduled - Human Follow-up`
    : `${meetingType} Scheduled - Needs Review`;
} else if (rawCallback) {
  // Not ready to talk now. The agent calls back itself at exactly the time they asked —
  // calling-hour snapping is off for explicit callbacks (SNAP_CALLBACKS_TO_WINDOW = false).
  const when = toDateTime(rawCallback);
  leadOutcome = leadOutcome || 'callback_requested';
  lastOutcome = 'Callback Requested';

  if (callbackCount + 1 > MAX_CALLBACKS) {
    callbackStamp = when ? localLabel(when) : (rawCallback || 'callback limit');
    callStatus = 'Callback Limit Reached - Human Follow-up';
  } else {
    // Named time -> dial then. Vague "call me later" / unparseable text -> +24h on
    // the client's clock. Explicit callbacks skip the business-hours window.
    let dialAt;
    if (when) {
      const asked = when.setZone(zone);
      const notBefore = asked.toMillis() < now.toMillis() ? now.setZone(zone) : asked;
      dialAt = (ENFORCE_CALL_WINDOW && SNAP_CALLBACKS_TO_WINDOW)
        ? nextCallableMoment(notBefore)
        : notBefore;
    } else {
      dialAt = now.setZone(zone).plus({ seconds: SEC_BEFORE_RETRY });
      if (ENFORCE_CALL_WINDOW && SNAP_CALLBACKS_TO_WINDOW) {
        dialAt = nextCallableMoment(dialAt);
      }
    }

    // A requested callback is not a failed-call retry, so it gets a fresh attempt budget.
    callbackStamp = localLabel(dialAt);
    retryAt = dialAt.setZone(TZ).toFormat(fmt);
    callStatus = 'Callback Scheduled';
    newCallbackCount = callbackCount + 1;
    attemptCount = 0;
  }
}

const businessFields = heardAnnouncement
  ? { prospect_interest_level: '', business_challenge_identified: '', next_action: '' }
  : {
      prospect_interest_level: body.prospect_interest_level || '',
      business_challenge_identified: body.business_challenge_identified || '',
      next_action: body.next_action || ''
    };

return [{
  json: {
    'Serial No': lead.lead_id,
    'Call Status': callStatus,
    conversation_id: lead.conversation_id,
    call_attempt_count: attemptCount,
    call_started_at: '',
    call_retry_at: retryAt,
    last_call_outcome: lastOutcome,
    lead_outcome: leadOutcome,
    callback_datetime: callbackStamp,
    callback_count: newCallbackCount,
    meeting_datetime: meetingStamp,
    meeting_type: meetingTypeOut,
    ...businessFields
  }
}];

// ElevenLabs sends every subscribed post-call event to ONE url, so
// /webhook/elevenlabs/call-initiation-failure receives two different payloads and only
// body.type tells them apart:
//
//   call_initiation_failure -> the call never connected  (handled by the other branch)
//   post_call_transcription -> the call ENDED, full transcript included
//
// The second one is what we want. It fires after the call is over, so its transcript is
// complete and nothing has to be fetched from the API.
const TZ = 'Asia/Kolkata';
const fmt = 'dd MMM yyyy HH:mm:ss';

const hook = $('Webhook Call Initiation Failure').first().json;
const payload = hook.body || hook;

const eventType = (payload.type || payload.event || '').toString().trim().toLowerCase();
if (eventType !== 'post_call_transcription') {
  return [];
}

const data = payload.data || {};
const meta = data.metadata || {};
const dyn = (data.conversation_initiation_client_data || {}).dynamic_variables || {};

const leadId = (dyn.lead_id || '').toString().trim();
const conversationId = (data.conversation_id || '').toString().trim();

if (!leadId && !conversationId) {
  return [];
}

// Tool requests and tool results arrive as turns with message: null, so only turns that
// actually contain words survive this filter.
const turns = Array.isArray(data.transcript) ? data.transcript : [];
const lines = turns
  .map((turn) => {
    const text = (turn && turn.message ? turn.message : '').toString().trim();
    if (!text) {
      return '';
    }
    const speaker = (turn.role || '').toString().toLowerCase() === 'agent' ? 'Agent' : 'Client';
    return speaker + ': ' + text;
  })
  .filter((line) => line !== '');

// The attempt number and the final verdict live on the lead row, not in this payload.
const row = $input
  .all()
  .map((item) => item.json)
  .find((r) => {
    const serial = (r['Serial No'] || '').toString().trim();
    const convo = (r.conversation_id || '').toString().trim();
    return (leadId && serial === leadId) || (conversationId && convo === conversationId);
  }) || {};

const startedAt = Number(meta.start_time_unix_secs || payload.event_timestamp || 0);
const timestamp = startedAt
  ? DateTime.fromSeconds(startedAt).setZone(TZ).toFormat(fmt)
  : DateTime.now().setZone(TZ).toFormat(fmt);

return [{
  json: {
    _transcript_serial: leadId || (row['Serial No'] || '').toString().trim(),
    _transcript_name: (dyn.client_name || row.Name || '').toString().trim(),
    _transcript_conversation_id: conversationId || (row.conversation_id || '').toString().trim(),
    _transcript_attempt: Number(row.call_attempt_count || 1),
    _transcript_status: (row['Call Status'] || '').toString().trim(),
    _transcript_timestamp: timestamp,
    _transcript_duration: Number(meta.call_duration_secs || 0),
    _transcript_text: lines.length ? lines.join('\n') : '(no transcript available)'
  }
}];

// Recover Leads when the client hung up before the agent tool webhook could fire.
// post_call_transcription always arrives after the call ends; if Call Status is still
// Calling, classify from this payload and clear the lock. If the agent path already
// updated the row, return nothing so we never overwrite a final status.
const TESTING = true;             // keep in sync with Determine Due Follow-ups
const ENFORCE_CALL_WINDOW = true; // keep in sync with Determine Due Follow-ups
const SNAP_CALLBACKS_TO_WINDOW = false;

const TZ = 'Asia/Kolkata';
const DEFAULT_TZ = 'Asia/Kolkata';
const SEC_BEFORE_RETRY = TESTING ? 60 : 24 * 60 * 60;
const MAX_CALL_ATTEMPTS = 3;
const MAX_CALLBACKS = 3;
const SHORT_CALL_SEC = 20;

const fmt = 'dd MMM yyyy HH:mm:ss';
const now = DateTime.now().setZone(TZ);

const hook = $('Webhook Call Initiation Failure').first().json;
const payload = hook.body || hook;
const eventType = (payload.type || payload.event || '').toString().trim().toLowerCase();
if (eventType !== 'post_call_transcription') {
  return [];
}

const data = payload.data || {};
const meta = data.metadata || {};
const analysis = data.analysis || {};
const dyn = (data.conversation_initiation_client_data || {}).dynamic_variables || {};
const collection = analysis.data_collection_results || analysis.data_collection || {};

const leadId = (dyn.lead_id || '').toString().trim();
const conversationId = (data.conversation_id || '').toString().trim();
if (!leadId && !conversationId) {
  return [];
}

const row = $input
  .all()
  .map((item) => item.json)
  .find((r) => {
    const serial = (r['Serial No'] || '').toString().trim();
    const convo = (r.conversation_id || '').toString().trim();
    return (leadId && serial === leadId) || (conversationId && convo === conversationId);
  });

if (!row) {
  return [];
}

const serial = (row['Serial No'] || leadId || '').toString().trim();
if (!serial) {
  return [];
}

// Agent tool already wrote a final status — leave it alone.
const previousStatus = (row['Call Status'] || '').toString().trim().toLowerCase();
if (previousStatus !== 'calling') {
  return [];
}

const attempts = Number(row.call_attempt_count || 1);
const callbackCount = Number(row.callback_count || 0);

// ---------------------------------------------------------------- client time zone
const resolveZone = (raw) => {
  const text = (raw || '').toString().trim();
  if (!text) return DEFAULT_TZ;
  const iana = text.split('(')[0].trim().replace(/\s+/g, '_');
  if (iana && DateTime.now().setZone(iana).isValid) return iana;
  const m = text.match(/UTC\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?/i);
  if (m) {
    const offset = 'UTC' + m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00');
    if (DateTime.now().setZone(offset).isValid) return offset;
  }
  return DEFAULT_TZ;
