const zone = resolveZone(row['time zone']);

const WINDOWS = { 2: [13, 16], 3: [13, 16], 4: [13, 16], 5: [12, 16] };
const TAIL_BUFFER_MIN = 10;

const windowEdges = (dt) => {
  const w = WINDOWS[dt.weekday];
  if (!w) return null;
  return {
    open: dt.set({ hour: w[0], minute: 0, second: 0, millisecond: 0 }),
    lastStart: dt.set({ hour: w[1], minute: 0, second: 0, millisecond: 0 })
      .minus({ minutes: TAIL_BUFFER_MIN })
  };
};

const nextCallableMoment = (dt) => {
  let cursor = dt;
  for (let i = 0; i < 15; i++) {
    const e = windowEdges(cursor);
    if (e) {
      if (cursor.toMillis() < e.open.toMillis()) return e.open;
      if (cursor.toMillis() < e.lastStart.toMillis()) return cursor;
    }
    cursor = cursor.plus({ days: 1 }).startOf('day');
  }
  return dt;
};

const localLabel = (dt) => dt.setZone(zone).toFormat('dd MMM yyyy HH:mm') + ' ' + zone;

// Flatten analysis / data-collection / dynamic vars into one bag the picker can read.
const flattenCollection = (obj) => {
  const out = {};
  if (!obj || typeof obj !== 'object') return out;
  for (const [key, val] of Object.entries(obj)) {
    if (val && typeof val === 'object' && 'value' in val) out[key] = val.value;
    else out[key] = val;
  }
  return out;
};

const body = {
  ...flattenCollection(collection),
  ...flattenCollection(analysis),
  ...(analysis.evaluation_criteria_results
    ? flattenCollection(analysis.evaluation_criteria_results)
    : {})
};

const pick = (...keys) => {
  for (const src of [body, data, analysis, dyn]) {
    for (const key of keys) {
      let value = src[key];
      if (value && typeof value === 'object' && 'value' in value) value = value.value;
      if (value !== undefined && value !== null && value.toString().trim() !== '') {
        return value.toString().trim();
      }
    }
  }
  return '';
};

const transcript = Array.isArray(data.transcript) ? data.transcript : [];
const otherSideText = transcript
  .filter((turn) => (turn && turn.role ? turn.role : '').toString().toLowerCase() !== 'agent')
  .map((turn) => (turn.message || turn.text || '').toString())
  .join(' ')
  .toLowerCase();
const fullText = transcript
  .map((turn) => (turn.message || turn.text || '').toString())
  .join(' ')
  .toLowerCase();

let rawMeeting = pick(
  'meeting_datetime', 'meeting_schedule_time', 'meeting_time', 'meeting_scheduled_at',
  'assessment_datetime', 'assessment_schedule_time', 'assessment_time',
  'appointment_datetime', 'appointment_time', 'demo_datetime'
);
let rawCallback = pick('callback_datetime', 'callback_time', 'call_back_datetime', 'callback_at');

let leadOutcome = (pick('lead_outcome') || '').toString();
let nextAction = (pick('next_action') || '').toString();

// Transcript fallbacks when the agent never submitted data collection before hang-up.
if (!leadOutcome) {
  if (/\bnot interested\b|\bno interest\b|\bnot looking\b|\bdon't call\b|\bdo not call\b|\bremove me\b|\bstop calling\b/.test(otherSideText)) {
    leadOutcome = 'not_interested';
  } else if (/\bcall me later\b|\bcall back\b|\bcall me back\b|\blater\b/.test(otherSideText)
    && !/\bmeeting\b|\bassessment\b|\bdemo\b/.test(otherSideText)) {
    leadOutcome = 'callback_requested';
    if (!rawCallback) rawCallback = 'later';
  }
}

const outcomeText = `${leadOutcome} ${nextAction} ${pick('meeting_type') || ''} ${fullText}`.toLowerCase();
const bookingWords = ['meeting', 'assessment', 'appointment', 'demo', 'consultation', 'audit', 'booked'];
const saysBooked = bookingWords.some((word) => outcomeText.includes(word))
  && !outcomeText.includes('not interested');

if (!rawMeeting && rawCallback && saysBooked) {
  rawMeeting = rawCallback;
  rawCallback = '';
}

// Structured outcome said callback but no datetime field — treat as vague callback.
if (!rawCallback && !rawMeeting
  && (leadOutcome.toLowerCase().includes('callback')
    || /\bcall me later\b|\bcall back\b/.test(outcomeText))) {
  rawCallback = 'later';
}

let meetingType = pick('meeting_type', 'appointment_type');
if (!meetingType && rawMeeting) {
  if (outcomeText.includes('assessment') || outcomeText.includes('audit')) meetingType = 'Assessment';
  else if (outcomeText.includes('demo')) meetingType = 'Demo';
  else meetingType = 'Meeting';
}

const TZ_WORDS = /\b(?:UTC|GMT|IST|EST|EDT|CST|CDT|MST|MDT|PST|PDT|BST|CET|CEST|EET|EEST|JST|KST|AEST|AEDT|AWST|SGT|HKT|NZST|NZDT|MSK|WAT|SAST|BRT)\b/gi;
const DATE_FORMATS = [
  'dd MMM yyyy HH:mm:ss', 'd MMM yyyy H:mm:ss',
  'dd MMM yyyy HH:mm', 'd MMM yyyy H:mm', 'd MMM yyyy h:mm a',
  'd MMMM yyyy H:mm', 'd MMMM yyyy h:mm a',
  'MMM d yyyy H:mm', 'MMM d yyyy h:mm a',
  'MMMM d yyyy H:mm', 'MMMM d yyyy h:mm a',
  'yyyy-M-d H:mm', 'yyyy-M-d h:mm a',
  'd/M/yyyy H:mm', 'd/M/yyyy h:mm a',
  'd-M-yyyy H:mm', 'd-M-yyyy h:mm a',
  'ccc d MMM yyyy H:mm', 'ccc d MMM yyyy h:mm a',
  'cccc d MMM yyyy H:mm', 'cccc d MMM yyyy h:mm a',
  'ccc d MMMM yyyy h:mm a', 'cccc d MMMM yyyy h:mm a',
  'd MMM yyyy', 'd MMMM yyyy', 'yyyy-M-d', 'd/M/yyyy', 'd-M-yyyy'
];

const toDateTime = (raw) => {
  if (!raw) return null;
  let text = raw.toString().trim();
  let useZone = zone;

  const named = text.match(/([A-Za-z]{3,}\/[A-Za-z_]+(?:\/[A-Za-z_]+)?)/);
  if (named && DateTime.now().setZone(named[1]).isValid) {
    useZone = named[1];
    text = text.replace(named[1], ' ');
  } else {
    const off = text.match(/\b(?:UTC|GMT)\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?/i);
    if (off) {
