  }

  text = text.replace(/\b(?:UTC|GMT)\s*[+-]\s*\d{1,2}(?::?\d{2})?/gi, ' ').replace(TZ_WORDS, ' ');
  text = text.replace(/\b(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s?m\.?(?![a-z])/gi,
    (whole, h, mi, ap) => h + ':' + (mi || '00') + ' ' + ap.toUpperCase() + 'M');
  text = text.replace(/\bat\b/gi, ' ').replace(/,/g, ' ');
  text = text.replace(/\s+/g, ' ').replace(/[.\s]+$/, '').trim();
  if (!text) return null;

  const attemptsList = [
    () => DateTime.fromISO(text, { zone: useZone }),
    () => DateTime.fromSQL(text, { zone: useZone }),
    () => DateTime.fromRFC2822(text, { zone: useZone })
  ].concat(DATE_FORMATS.map((f) => () => DateTime.fromFormat(text, f, { zone: useZone })));

  for (const attempt of attemptsList) {
    try {
      const parsed = attempt();
      if (parsed && parsed.isValid) return parsed;
    } catch (err) {
      // next format
    }
  }
  return null;
};

const announcementHints = [
  'does not exist', "doesn't exist", 'not in service', 'no longer in service',
  'out of service', 'has been disconnected', 'been disconnected', 'unallocated',
  'not allocated', 'unassigned', 'not a valid number', 'not a working number',
  'invalid number', 'wrong number', 'number you have dialed', 'number you have dialled',
  'number you are trying to reach', 'number you have called',
  'cannot be completed as dialed', 'cannot be completed as dialled',
  'check the number', 'number does not belong'
];

const heardAnnouncement = otherSideText.length > 0
  && announcementHints.some((hint) => otherSideText.includes(hint));

const durationSec = Number(meta.call_duration_secs || meta.callDurationSecs || 0);
// post_call_transcription only fires after the call has ended.
const convoFinished = true;
const nobodySpoke = transcript.length > 0 && otherSideText.trim().length === 0;

let callStatus = 'Completed';
let lastOutcome = leadOutcome || 'answered';
let retryAt = '';
let attemptCount = attempts;
let newCallbackCount = callbackCount;
let meetingStamp = '';
let callbackStamp = '';
let meetingTypeOut = '';

if (heardAnnouncement) {
  leadOutcome = 'invalid_number';
  lastOutcome = 'Invalid Number';
  callStatus = 'Invalid Number - No Retry';
  attemptCount = MAX_CALL_ATTEMPTS;
} else if (nobodySpoke && convoFinished && durationSec > 0 && durationSec <= SHORT_CALL_SEC) {
  leadOutcome = leadOutcome || 'no_response';
  lastOutcome = 'No Response';
  if (attempts < MAX_CALL_ATTEMPTS) {
    callStatus = 'No Response - Retry Scheduled';
    const target = now.setZone(zone).plus({ seconds: SEC_BEFORE_RETRY });
    const dialAt = ENFORCE_CALL_WINDOW ? nextCallableMoment(target) : target;
    retryAt = dialAt.setZone(TZ).toFormat(fmt);
  } else {
    callStatus = 'No Response - Retry Exhausted';
  }
} else if (rawMeeting) {
  const when = toDateTime(rawMeeting);
  meetingTypeOut = meetingType;
  meetingStamp = when ? localLabel(when) : rawMeeting;
  leadOutcome = leadOutcome || `${meetingType.toLowerCase()}_booked`;
  lastOutcome = `${meetingType} Booked`;
  callStatus = when
    ? `${meetingType} Scheduled - Human Follow-up`
    : `${meetingType} Scheduled - Needs Review`;
} else if (rawCallback) {
  const when = toDateTime(rawCallback);
  leadOutcome = leadOutcome || 'callback_requested';
  lastOutcome = 'Callback Requested';

  if (callbackCount + 1 > MAX_CALLBACKS) {
    callbackStamp = when ? localLabel(when) : (rawCallback || 'callback limit');
    callStatus = 'Callback Limit Reached - Human Follow-up';
  } else {
    let dialAt;
    if (when) {
      const asked = when.setZone(zone);
      const notBefore = asked.toMillis() < now.toMillis() ? now.setZone(zone) : asked;
      dialAt = (ENFORCE_CALL_WINDOW && SNAP_CALLBACKS_TO_WINDOW)
        ? nextCallableMoment(notBefore)
        : notBefore;
    } else {
      dialAt = now.setZone(zone).plus({ seconds: SEC_BEFORE_RETRY });
      if (ENFORCE_CALL_WINDOW && SNAP_CALLBACKS_TO_WINDOW) {
        dialAt = nextCallableMoment(dialAt);
      }
    }
    callbackStamp = localLabel(dialAt);
    retryAt = dialAt.setZone(TZ).toFormat(fmt);
    callStatus = 'Callback Scheduled';
    newCallbackCount = callbackCount + 1;
    attemptCount = 0;
  }
} else {
  // Normal end, including "not interested" — same as agent-tool path: Completed.
  if (leadOutcome.toLowerCase().includes('not_interested')
    || leadOutcome.toLowerCase().includes('not interested')) {
    leadOutcome = 'not_interested';
    lastOutcome = 'Not Interested';
  }
  callStatus = 'Completed';
}

const businessFields = heardAnnouncement
  ? { prospect_interest_level: '', business_challenge_identified: '', next_action: '' }
  : {
      prospect_interest_level: pick('prospect_interest_level') || '',
      business_challenge_identified: pick('business_challenge_identified') || '',
      next_action: nextAction || pick('next_action') || ''
    };

return [{
  json: {
    'Serial No': serial,
    'Call Status': callStatus,
    conversation_id: conversationId || (row.conversation_id || '').toString().trim(),
    call_attempt_count: attemptCount,
    call_started_at: '',
    call_retry_at: retryAt,
    last_call_outcome: lastOutcome,
    lead_outcome: leadOutcome,
    callback_datetime: callbackStamp,
    callback_count: newCallbackCount,
    meeting_datetime: meetingStamp,
    meeting_type: meetingTypeOut,
    ...businessFields
  }
}];
